function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

function splitTeams(names, opts){
  opts=opts||{}; var seed=opts.seed!=null?opts.seed:1; var r=rngFactory(seed);
  var list=(typeof names==='string' ? names.split(/[\n,，;；\s]+/) : (names||[]))
    .map(function(s){ return String(s).trim(); }).filter(Boolean);
  var cnt=opts.teams!=null?opts.teams:2;
  if(cnt<1) cnt=1;
  if(list.length && cnt>list.length) cnt=list.length;
  var arr=list.slice();
  for(var i=arr.length-1;i>0;i--){ var j=Math.floor(r()*(i+1)); var t=arr[i]; arr[i]=arr[j]; arr[j]=t; }
  var teams=[];
  for(var k=0;k<cnt;k++) teams.push([]);
  for(var m=0;m<arr.length;m++) teams[m%cnt].push(arr[m]);
  return {ok:true, teams:teams, count:cnt, total:list.length};
}

var EXPORTS={splitTeams:splitTeams};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TeamForgePure = EXPORTS; }
